// JACK'S WEBSOCKET BRIDGE (PORT 8081)
// ==========================================
const WebSocket = require('ws');
const wsServer = new WebSocket.Server({ host: '0.0.0.0', port: 8081 }, () => {
    console.log(`[JACK] Warlord WebSocket Bridge running on ws://0.0.0.0:8081`);
    console.log(`=======================================================`);
    console.log(`MCNC RUNTIME ACTIVE // LIVE STREAMING ENGAGED`);
    console.log(`=======================================================`);
});

// Monty's Active Brain State
let activeProvider = 'nvidia'; 
let activeModel = 'llama-3.3-70b-instruct';
let isMicRecording = false; // Tracks mic state

wsServer.on('connection', (ws) => {
    console.log('[JACK] Frontend connected to MCNC Master UI.');

    ws.on('message', async (message) => {
        try {
            const packet = JSON.parse(message);
            
            // 1. HANDLE NEURAL PATHWAY SHIFT (BRAIN SWITCH)
            if (packet.type === 'SWITCH_BRAIN') {
                activeProvider = packet.provider;
                activeModel = packet.model;
                console.log(`[JACK] Brain Switched -> Provider: ${activeProvider.toUpperCase()} | Model: ${activeModel}`);
            }
            
            // 2. HANDLE EXEC DISPATCH
            else if (packet.type === 'MONTY_EXEC_DISPATCH') {
                console.log(`[JACK] Routing prompt to ${activeProvider.toUpperCase()} (${activeModel}): "${packet.promptText}"`);
                
                setTimeout(() => {
                    let responseText = `Link active on ${activeProvider.toUpperCase()}. Awaiting instructions.`;
                    ws.send(JSON.stringify({
                        type: 'MONTY_EXEC_UPDATE',
                        speaker: 'CHIEF OF STAFF // MONTY 2',
                        text: responseText,
                        color: 'Goldenrod'
                    }));
                }, 600); 
            }
            
            // 3. HANDLE SYSTEM OVERRIDES
            else if (packet.type === 'WAR_ROOM_APPROVE') {
                console.log(`[JACK] War Room Approval received. Bypassing sandbox rules.`);
            }

            // 4. RESTORED: HANDLE MIC TOGGLE
            else if (packet.type === 'UI_TOGGLE_MIC') {
                console.log(`[JACK] Mic toggle requested from ${packet.source}.`);
                isMicRecording = !isMicRecording;
                
                // Blast the state back to the UI so the mic icon turns red (recording)
                ws.send(JSON.stringify({ 
                    type: 'UI_MIC_STATUS', 
                    status: isMicRecording ? 'listening' : 'idle' 
                }));

                // WARLORD NOTE: If you previously had a specific script execution here 
                // (like a python Whisper script), it gets triggered inside this block.
            }
            
        } catch (err) {
            console.error('[JACK] Error parsing WebSocket message:', err);
        }
    });

    ws.on('close', () => {
        console.log('[JACK] Frontend UI disconnected.');
    });
});

